let body = $json.body;
if (typeof body === "string") { try { body = JSON.parse(body); } catch (e) { body = null; } }
if (!body || typeof body !== "object" || Array.isArray(body)) body = $json;

// Génération d'un UUID aléatoire non devinable (jeton de paiement).
// Si require('crypto') est refusé, ajouter NODE_FUNCTION_ALLOW_BUILTIN=crypto dans n8n.
let payer_token;
try { payer_token = require('crypto').randomUUID(); }
catch (e) {
  if (globalThis.crypto && globalThis.crypto.randomUUID) payer_token = globalThis.crypto.randomUUID();
  else throw new Error("Impossible de générer un UUID sécurisé : autoriser le module crypto dans n8n");
}

const SITE_URL = "https://site.g3.madeleine-riviera.fr";
const demande = (body.demande && typeof body.demande === "object") ? body.demande : {};
const montant = Number(body.montant_eur) > 0 ? Number(body.montant_eur) : 100; // cotisation 100 €/an (H5)
return {
  json: {
    demande: demande,
    montant_eur: montant,
    payer_token: payer_token,
    payer_url: SITE_URL + "/payer/" + payer_token
  }
};
